const ll MOD = 1e9 + 7;

ll modmul(ll a, ll b) { return (a % MOD) * (b % MOD) % MOD; }  // ≤ (1e9)² < 9.2e18 ✓

ll modpow(ll base, ll exp) {              // also = modinv(base) when exp = MOD-2
    ll r = 1; base %= MOD;
    while (exp > 0) {
        if (exp & 1) r = modmul(r, base);
        base = modmul(base, base);
        exp >>= 1;
    }
    return r;
}
ll moddiv(ll a, ll b) { return modmul(a, modpow(b, MOD - 2)); }  // Fermat inverse
